# Inventors Ladder: The Age of Electricity (course key invelec). Helpers come from scripts/inventors/build.py.
# Faraday matches the Great Books rung gb19.faraday-experimental-researches (life 1791–1867; Experimental Researches
# 1832–1855; the Candle lectures of 1860–1861). Safety: no kite flying in storms, no mains electricity, no hands-on
# experiments here; the From Scratch course holds the projects.

LESSONS = {
 "franklin": LES([
  P("Benjamin Franklin (1706–1790) was born in Boston, the fifteenth of seventeen children of a candle and soap maker. He ran away to Philadelphia at seventeen, became a printer, and grew rich publishing a newspaper and <i>Poor Richard's Almanack</i>. He retired from business in 1748, partly to have time for science. Later he became one of the best-known statesmen of the American founding."),
  K("Franklin's science started with play and ended with useful things. He proposed that electricity is <b>one fluid</b> that objects can have too much of (<b>positive</b>, plus) or too little of (<b>negative</b>, minus); he showed that <b>lightning is electricity</b>; and he invented the <b>lightning rod</b> to lead it safely into the ground. He also invented a better stove and bifocal glasses, and patented none of them."),
  H("How the idea came"),
  P("In his <i>Autobiography</i> Franklin tells how he first saw electric tricks in Boston, and how a gift of a glass tube from London set him working. (Historians date the Boston demonstrations to 1743, a little earlier than he remembered.)"),
  Q("In 1746, being at Boston, I met there with a Dr. Spence, who was lately arrived from Scotland, and show'd me some electric experiments. They were imperfectly perform'd, as he was not very expert; but, being on a subject quite new to me, they equally surpris'd and pleased me. Soon after my return to Philadelphia, our library company receiv'd from Mr. P. Collinson, Fellow of the Royal Society of London, a present of a glass tube, with some account of the use of it in making such experiments. I eagerly seized the opportunity of repeating what I had seen at Boston.",
    "Benjamin Franklin", "Autobiography", "Harvard Classics, vol. 1 (P. F. Collier & Son, 1909)", "https://archive.org/details/Harvard-Classics", "Spelling as printed. The lecturer's name is usually given as Archibald Spencer."),
  P("Rubbing a glass tube with silk charged it. Franklin and his friends found that a person standing on wax could be charged, and that a pointed metal rod drew charge off quietly while a blunt one gave a spark. He wrote his findings in letters to Peter Collinson in London, who had them printed as a book in 1751."),
  H("Plus and minus"),
  P("Others thought there were two kinds of electricity. Franklin suggested one: rubbing does not make it, it only moves it, so one object gains what the other loses. He called a surplus <i>positive</i> or <i>plus</i>, and a shortage <i>negative</i> or <i>minus</i>. We still use those words, and the idea that charge is conserved is one of the firm laws of physics."),
  V("iv-charge", None, "Rub the glass with the silk. Charge moves from one to the other, but the total stays zero. Then bring two charged balls near each other: like charges push apart, unlike charges pull together."),
  EX("Charge moves, it isn't made", "Before rubbing, glass and silk each have charge 0. After rubbing, the glass has +6 units. What is the silk's charge?",
     ["The total must stay 0, since charge only moves.", "$6 + s = 0$, so $s = -6$."], "−6 units."),
  H("Lightning is electricity"),
  P("Franklin listed ways lightning and electric sparks were alike: light, crooked paths, a crack, melting metal, a sulfur smell. In 1750 he proposed a test: a tall pointed iron rod on a high building, insulated at the bottom, should draw charge from a storm cloud. In May 1752 French experimenters led by Thomas-François Dalibard did it at Marly, near Paris, and got sparks from the rod. Franklin, not yet knowing, tried a kite in Philadelphia. His letter describing it was printed that October."),
  Q("As soon as any of the thunder clouds come over the kite, the pointed wire will draw the electric fire from them, and the kite, with all the twine, will be electrified, and the loose filaments of the twine will stand out every way, and be attracted by an approaching finger.",
    "Benjamin Franklin", "Letter of October 19, 1752", "New Experiments and Observations on Electricity (London, 1754 printing), Letter X", "https://archive.org/details/newexperimentsob00fran", "Spelling modernized (the long s)."),
  N('<div class="iv-safe"><p class="iv-box-lab"><span aria-hidden="true">⚠️</span> Never try this</p><p>Flying a kite in a thunderstorm can kill you. Franklin\'s kite was not struck by lightning; the string only picked up charge from the air, and even that was dangerous. In 1753 the scientist Georg Wilhelm Richmann was killed in St. Petersburg by lightning that came down an insulated rod during a similar experiment. Fly kites only in fair weather, in open fields far from power lines.</p></div>'),
  LEGEND("<p>Franklin's letter does not give the date or say who helped. The details come from Joseph Priestley's <i>History of Electricity</i> (1767), written with Franklin's help: June 1752, with his son William. A few modern writers have questioned whether the kite flight happened at all, since Franklin wrote so little about it; most historians accept that it did. The famous pictures of lightning striking the kite are wrong either way.</p>"),
  H("The lightning rod"),
  P("If a pointed rod can draw charge from a cloud, a grounded rod can lead a lightning strike safely down into the earth instead of through a building. Franklin published the idea in <i>Poor Richard's Almanack</i> for 1753. Rods spread across America and Europe, and grounded lightning protection is still used today, installed by trained professionals."),
  H("The stove and the bifocals"),
  P("Around 1742 Franklin designed an iron fireplace that stood out in the room and warmed it better while burning less wood. He described it in a 1744 pamphlet. The governor offered him a patent, and he said no:"),
  Q("That, as we enjoy great advantages from the inventions of others, we should be glad of an opportunity to serve others by any invention of ours; and this we should do freely and generously.",
    "Benjamin Franklin", "Autobiography", "Harvard Classics, vol. 1 (P. F. Collier & Son, 1909)", "https://archive.org/details/Harvard-Classics"),
  P("In old age he needed one pair of glasses to see far and another to read. He had the lenses cut in half and put the two halves in one frame: reading half below, distance half above. He described his \"double spectacles\" in a letter of 1785. Others may have had the same idea, but Franklin's is the best-known early account."),
  TL([
   ("1706", "Born in Boston"),
   ("1723", "Arrives in Philadelphia"),
   ("c. 1742", "Designs the Pennsylvania fireplace (Franklin stove)"),
   ("1743–1746", "Sees electric demonstrations; starts experiments with a glass tube"),
   ("1750", "Proposes the sentry-box (rod) experiment and the lightning rod"),
   ("1751", "His letters on electricity printed in London"),
   ("May 1752", "Dalibard draws sparks from a rod at Marly, France"),
   ("June 1752", "The kite experiment in Philadelphia (date from Priestley)"),
   ("1753", "Copley Medal of the Royal Society"),
   ("1785", "Describes his double spectacles (bifocals)"),
   ("1790", "Dies in Philadelphia"),
  ]),
  EX("Ages", "Franklin was born in 1706. How old was he in June 1752, at the time of the kite?",
     ["$1752 - 1706 = 46$. His birthday was in January, so by June he had turned 46."], "46."),
  H("What it led to"),
  P("Franklin's words, positive, negative, battery, charge, conductor, are still the words of electricity. The lightning rod saved countless buildings and ships. And his refusal to patent shows one view of invention: that ideas built on other people's work should be shared."),
  M("Thinking Franklin discovered electricity. People had studied static electricity for centuries. Franklin's contributions were the one-fluid idea, plus and minus, and proof that lightning is electric."),
  TRYIT([("lemon-battery", "Make a battery, the steady electricity Franklin never had"), ("electromagnet", "Build an electromagnet")]),
  P("Read more: " + GK("Benjamin_Franklin", "Benjamin Franklin") + ", " + GK("Lightning_rod", "Lightning rod") + ", " + GK("Franklin_stove", "Franklin stove") + " and " + GK("Bifocals") + "."),
  TRY,
 ], "franklin_auto", "franklin_exp", "g_franklin"),

 "volta": LES([
  P("Alessandro Volta (1745–1827) was born in Como, in northern Italy, and became professor of natural philosophy at the University of Pavia. He was a careful experimenter who had already invented a device for making static charge (the electrophorus, 1775) and discovered methane gas in marsh mud. His great invention came out of an argument."),
  K("Volta stacked discs of <b>two different metals</b> with <b>brine-soaked card</b> between each pair. The stack, his <b>pile</b> of 1800, gave the first <b>steady electric current</b>. Each pair adds its voltage, so a taller pile pushes harder."),
  H("The problem: frogs' legs"),
  P("In the 1780s Luigi Galvani, a doctor in Bologna, saw dissected frogs' legs twitch when touched with two different metals. In 1791 he published the idea that animals hold their own \"animal electricity\" in their nerves and muscles, and the metals only let it flow. Volta repeated the experiments, at first agreeing, then doubting. He suspected the electricity came from the <b>two different metals</b> touching through something wet, and the frog's leg was just a very sensitive detector."),
  H("What he tried"),
  P("Volta tested pairs of metals in many combinations and ranked them by how strong an effect they gave. Zinc with silver or copper was among the best. He found that one pair gave only a tiny effect, so he tried adding more: cup after cup of salt water joined by metal strips (his \"crown of cups\"), and a pile of discs. The more pairs, the stronger the shock. On March 20, 1800, he described the pile in a letter to Sir Joseph Banks, President of the Royal Society in London."),
  Q("The apparatus to which I allude, and which will, no doubt, astonish you, is only the assemblage of a number of good conductors of different kinds arranged in a certain manner.",
    "Alessandro Volta", "Letter to Sir Joseph Banks, March 20, 1800", "English translation in The Philosophical Magazine, vol. 7 (1800)", "https://archive.org/details/s2id13415780", "Spelling modernized."),
  P("In the same letter he lists the recipe: thirty, forty, sixty or more pieces of copper or silver, each against a piece of zinc, with layers of water, salt water, or card soaked in them between each pair, always in the same order."),
  V("iv-pile", None, "Add zinc, card and copper layers. Each zinc–copper pair adds about 0.8 volts (the exact value depends on the metals and the liquid). Put a pair in backward and it subtracts."),
  EX("How tall a pile?", "Each pair in a pile gives 0.8 volts. How many pairs do you need for 12 volts?",
     ["Pairs add up: $n \\times 0.8 = 12$.", "$n = 12 \\div 0.8 = 15$."], "15 pairs."),
  W("Inside each cell, chemical reactions at the two metals push electrons around the circuit; the brine lets charged particles move between them. Volta himself thought the contact of the metals did it. Later scientists showed the chemistry is the real source, which is why a pile runs down as the zinc is eaten away."),
  H("Who was right?"),
  P("The argument between Galvani and Volta is a good example of two scientists each holding part of the truth. Volta was right that the pile's electricity comes from different metals and a liquid, not from the frog. Galvani was right that nerves and muscles use electricity: today we know nerve signals are electrical, and the science of bioelectricity grew from his work. Galvani died in 1798, before the pile was built."),
  TL([
   ("1745", "Volta born in Como"),
   ("1775", "Invents the electrophorus"),
   ("1780s", "Galvani's frog experiments in Bologna"),
   ("1791", "Galvani publishes on animal electricity"),
   ("1792–1799", "Volta tests metal pairs and argues for metallic electricity"),
   ("1800", "Volta describes the pile in a letter to the Royal Society"),
   ("1800", "Within weeks, William Nicholson and Anthony Carlisle use a pile to split water into hydrogen and oxygen"),
   ("1801", "Volta shows the pile to Napoleon in Paris"),
   ("1827", "Volta dies in Como"),
   ("1881", "The unit of voltage is named the volt"),
  ]),
  EX("A long debate", "Galvani published in 1791 and Volta's pile came in 1800. How many years did the debate run before the pile?",
     ["$1800 - 1791 = 9$."], "9 years."),
  H("What it led to"),
  P("The pile gave scientists, for the first time, a current that kept flowing. Within a few years Humphry Davy used huge piles to discover sodium and potassium. Ørsted (1820) used one to find that a current moves a compass needle, and Faraday built his motor on that. Every battery today, from a flashlight cell to a car battery, follows Volta's plan."),
  M("Thinking a battery stores electricity like a jar stores water. It stores chemicals; the reaction between them pushes charge around a circuit when you connect it."),
  TRYIT([("lemon-battery", "Build Volta's idea yourself with lemons, zinc-coated nails and copper")]),
  P("Read more: " + GK("Alessandro_Volta", "Alessandro Volta") + " and " + GK("Voltaic_pile", "Voltaic pile") + "."),
  TRY,
 ], "volta1800", "g_volta"),

 "faraday": LES([
  P("Michael Faraday (1791–1867) was the son of a London blacksmith. He left school at 13 and was apprenticed to a bookbinder, where he read the science books he bound. In 1812 a customer gave him tickets to hear Humphry Davy lecture at the Royal Institution. Faraday wrote up his notes, bound them, and sent them to Davy. In 1813 Davy hired him as a laboratory assistant. He stayed at the Royal Institution for the rest of his working life and became the greatest experimenter of his age."),
  K("Faraday found that electricity and magnetism can turn into motion and back: a current in a magnetic field makes <b>motion</b> (the motor, 1821), and a <b>changing</b> magnetic field makes a current (induction, 1831). The second is how nearly all our electricity is made."),
  H("The motor, 1821"),
  P("In 1820 Hans Christian Ørsted in Copenhagen found that a wire carrying current pushes a compass needle sideways. Faraday wondered: if a current pushes a magnet, could a magnet push a current-carrying wire around and around? In September 1821 he hung a wire into a cup of mercury with a magnet standing in the middle, and connected a battery. The wire swept in circles around the magnet: the first device to turn electricity into continuous motion."),
  N("Faraday used mercury, which is poisonous. The From Scratch project uses a safe modern version: a battery, a small magnet and copper wire."),
  H("Induction, 1831: the key is change"),
  P("If electricity can make magnetism, can magnetism make electricity? Faraday tried for years. On August 29, 1831, he wound two coils of wire on an iron ring, one joined to a battery and the other to a galvanometer, a meter for current. When he connected the battery, the needle jumped, then went back. When he disconnected it, the needle jumped the other way. While the current flowed steadily, nothing happened."),
  Q("One of these helices was connected with a galvanometer, and the other with a battery of one hundred pairs of plates four inches square, with double coppers, and well charged. When the contact was made, there was a sudden and very slight effect at the galvanometer, and there was also a similar slight effect when the contact with the battery was broken. But whilst the voltaic current was continuing to pass through the one helix, no galvanometrical appearances of any effect like induction upon the other helix could be perceived.",
    "Michael Faraday", "Experimental Researches in Electricity, First Series, paragraph 10", "Philosophical Transactions of the Royal Society of London, vol. 122 (1832)", "https://archive.org/details/philtrans01461252", "Slightly shortened."),
  P("Weeks later he tried a plain bar magnet and a coil."),
  Q("One end of this magnet was introduced into the axis of the helix, and then, the galvanometer-needle being stationary, the magnet was suddenly thrust in; immediately the needle was deflected in the same direction as if the magnet had been formed by either of the two preceding processes. Being left in, the needle resumed its first position, and then the magnet being withdrawn the needle was deflected in the opposite direction.",
    "Michael Faraday", "Experimental Researches in Electricity, First Series, paragraph 39", "Philosophical Transactions of the Royal Society of London, vol. 122 (1832)", "https://archive.org/details/philtrans01461252", "Figure references left out."),
  V("iv-induction", None, "Drag the magnet into the coil and out again, or press Shake. The meter only moves while the magnet moves. Add turns or move faster for a bigger current."),
  K("The voltage made in a coil depends on how fast the magnetic field through it changes, times the number of turns: $\\mathcal{E} = N\\dfrac{\\Delta\\Phi}{\\Delta t}$ (size only). No change, no current."),
  EX("Faster means more", "Pushing a magnet into a coil in 0.5 s makes 0.2 volts. What do you get pushing it in, the same way, in 0.1 s?",
     ["The same change happens in $\\dfrac{0.5}{0.1} = 5$ times less time.", "So the voltage is 5 times larger: $5 \\times 0.2 = 1$ V."], "1 volt."),
  P("That autumn he turned a copper disc between the poles of a big magnet and drew a steady current from it: the first generator, or dynamo. Joseph Henry in America found induction independently at about the same time; Faraday published first."),
  H("Teaching"),
  P("Faraday began the Royal Institution's Christmas Lectures for young people in 1825, and they still run. His six lectures on <i>The Chemical History of a Candle</i>, given at Christmas 1860–1861, are among the most famous science talks ever printed."),
  Q("There is not a law under which any part of this universe is governed which does not come into play, and is touched upon in these phenomena. There is no better, there is no more open door by which you can enter into the study of natural philosophy, than by considering the physical phenomena of a candle.",
    "Michael Faraday", "The Chemical History of a Candle, Lecture I", "Edited by William Crookes (Chatto and Windus, 1908 impression)", "https://archive.org/details/chemicalhistoryo00faraiala"),
  TL([
   ("1791", "Born in Newington Butts, near London"),
   ("1805", "Apprenticed to the bookbinder George Riebau"),
   ("1812", "Hears Humphry Davy's lectures"),
   ("1813", "Becomes Davy's assistant at the Royal Institution"),
   ("1820", "Ørsted finds that a current moves a compass needle"),
   ("1821", "Faraday's electromagnetic rotation: the first motor"),
   ("1825", "Starts the Christmas Lectures"),
   ("1831", "Discovers electromagnetic induction; builds the first generator"),
   ("1832–1855", "Publishes Experimental Researches in Electricity"),
   ("1860–1861", "Lectures on The Chemical History of a Candle"),
   ("1867", "Dies at Hampton Court"),
  ]),
  EX("From motor to generator", "How many years after his motor (1821) did Faraday discover induction (1831)?",
     ["$1831 - 1821 = 10$."], "10 years: a decade of trying."),
  H("What it led to"),
  P("Every power station that spins a turbine, whether driven by steam, water or wind, uses Faraday's induction. So does every transformer. James Clerk Maxwell later put Faraday's ideas of fields into equations, which predicted radio waves. The unit of capacitance, the farad, is named after him."),
  M("Thinking a magnet sitting inside a coil makes a current. It makes a current only while the magnet, or the coil, is moving or the field is changing."),
  GB([("/great-books/the-19th-century/faraday-experimental-researches/", "Faraday: Experimental Researches in Electricity", "the 1831 induction experiments in Faraday's own words")]),
  N('Also read Faraday\'s lectures for young people: <a href="/homeschool/science/chemical-history-of-a-candle/">The Chemical History of a Candle</a>.'),
  TRYIT([("simple-motor", "Build a simple motor like Faraday's 1821 rotation"), ("hand-generator", "Make current with a magnet and a coil, as in 1831")]),
  P("Read more: " + GK("Michael_Faraday", "Michael Faraday") + "."),
  TRY,
 ], "faraday_er", "faraday_candle", "g_faraday"),

 "morse": LES([
  P("Samuel F. B. Morse (1791–1872) was a painter before he was an inventor. Born in Charlestown, Massachusetts, he studied art in London and painted portraits. In 1825, while he was in Washington painting a portrait, his wife died at home in New Haven; the letter bringing the news took days to reach him. Some writers link his later interest in fast messages to that loss."),
  K("Morse's telegraph used a battery, a switch (the <b>key</b>) and an <b>electromagnet</b> far away that clicked when the current flowed. Short and long clicks, <b>dots and dashes</b>, spelled out letters. A message could cross a country in moments."),
  H("How the idea came"),
  P("In 1832, sailing home from Europe on the ship <i>Sully</i>, Morse talked with a passenger, Charles Jackson, about electromagnets. Morse reasoned that if current could be sensed at any distance along a wire, signals could be sent. He sketched ideas in a notebook on the voyage."),
  H("What he tried, and who helped"),
  P("Morse knew little science, and his first instrument worked only over short distances. Two people made the difference. Leonard Gale, a chemistry professor, showed him the work of the American scientist <b>Joseph Henry</b>, who had found how to wind electromagnets with many turns and use batteries of many cells so current could push through long wires. And <b>Alfred Vail</b>, a skilled mechanic, joined in 1837, built much better instruments, and helped shape the code. Historians still discuss how much of the dot-and-dash alphabet was Vail's."),
  P("The first code used numbers that stood for words in a code book. It was replaced by a code for letters. Common letters got short codes: E is a single dot, T a single dash. That makes messages faster, an idea used in data compression today."),
  V("iv-morse", None, "Type a word to hear and see it in Morse code, or tap the key yourself and watch it decode. A dash is three dot-lengths; letters are separated by three, words by seven."),
  TB(["Letter", "Code", "Letter", "Code"], [
   ("E", "·", "T", "−"), ("A", "· −", "N", "− ·"), ("S", "· · ·", "O", "− − −"), ("H", "· · · ·", "R", "· − ·"),
  ], "A few letters of International Morse Code, the version used today (it differs a little from Morse and Vail's original American code)."),
  EX("Counting dot-lengths", "In Morse timing a dot is 1 unit, a dash 3, the gap inside a letter 1. How many units long is the letter S (· · ·)?",
     ["Three dots: $3 \\times 1 = 3$ units.", "Two gaps between them: $2 \\times 1 = 2$ units.", "$3 + 2 = 5$."], "5 units."),
  H("What hath God wrought"),
  P("In 1843 Congress paid 30,000 dollars to build a test line from Washington to Baltimore, about 40 miles. On May 24, 1844, Morse sent the first official message from the Supreme Court chamber in the Capitol to Vail in Baltimore: \"What hath God wrought.\" The words, from the Bible (Numbers 23:23), were chosen by Annie Ellsworth, the young daughter of a friend who had helped him."),
  LEGEND("<p>Morse is often called <i>the</i> inventor of the telegraph. In Britain, William Cooke and Charles Wheatstone patented a needle telegraph in 1837 and had one working on a railway by 1839. Others built electric telegraphs too. Morse's system won in America and much of the world because it was simple, needed only one wire, and its code could be sent by ear and by hand.</p>"),
  TL([
   ("1791", "Morse born in Charlestown, Massachusetts"),
   ("1831", "Joseph Henry demonstrates an electromagnet ringing a bell over a long wire"),
   ("1832", "Morse's idea aboard the Sully"),
   ("1837", "Alfred Vail joins; Cooke and Wheatstone patent their telegraph in Britain"),
   ("1840", "Morse receives a U.S. patent"),
   ("1843", "Congress funds the Washington–Baltimore line"),
   ("1844", "\"What hath God wrought\""),
   ("1861", "Telegraph lines cross the United States"),
   ("1866", "A lasting telegraph cable crosses the Atlantic"),
   ("1872", "Morse dies in New York"),
  ]),
  EX("Across the country", "The Washington–Baltimore line opened in 1844, and lines crossed the continent in 1861. How many years later was that?",
     ["$1861 - 1844 = 17$."], "17 years."),
  H("What it led to"),
  P("The telegraph changed news, business and railways: trains could be scheduled safely, and news arrived the same day. Morse code was used by ships and radio operators for over a century. The telegraph's electromagnet relay, which lets a weak current switch a stronger one, is an ancestor of the switches inside computers."),
  M("Thinking the telegraph sent sound along the wire. It sent pulses of current; an electromagnet at the far end turned them into clicks or marks on paper."),
  TRYIT([("telegraph", "Build a telegraph with a battery, a switch and an electromagnet"), ("electromagnet", "Start with the electromagnet")]),
  P("Read more: " + GK("Samuel_Morse", "Samuel Morse") + " and " + GK("Electrical_telegraph", "Electrical telegraph") + "."),
  TRY,
 ], "loc_morse", "g_morse"),

 "bell": LES([
  P("Alexander Graham Bell (1847–1922) was born in Edinburgh, Scotland, into a family of speech teachers. His father invented Visible Speech, a set of symbols showing how to make each sound. His mother was nearly deaf, and so was his wife, Mabel Hubbard. Bell moved to Canada with his family in 1870 and to Boston in 1871, where he taught deaf students to speak. Sound and hearing were his life's work."),
  K("A telegraph sends <b>on and off</b>. Bell's telephone sent a current that <b>rises and falls in the same shape as the sound wave</b> of a voice. At the far end, the changing current moved a thin plate (a diaphragm) the same way, and that made the sound again."),
  H("The problem"),
  P("Telegraph companies wanted to send several messages at once on one wire. Bell, like the inventor Elisha Gray and others, worked on a \"harmonic telegraph\" that would send each message as a different musical note. Bell, who knew how speech is built from many tones together, began to wonder whether a wire could carry all the tones of a voice."),
  H("What he tried"),
  P("Bell worked with a young machinist, <b>Thomas Watson</b>. On June 2, 1875, a reed stuck on Watson's transmitter; when Watson plucked it free, Bell heard the twang come through his receiver, with all its overtones. The changing current from a vibrating reed near a magnet could carry the shape of a sound. Over the next months they built transmitters with a diaphragm to catch the voice."),
  V("iv-phone", None, "Choose a sound. The telegraph can only send on or off. The telephone's current copies the wave's shape, so the receiver can rebuild the sound."),
  P("Bell's patent, U.S. No. 174,465, was filed on February 14, 1876, and granted on March 7. Three days later, using a new transmitter with a needle dipping into acid water, Bell spoke to Watson in the next room. His notebook records it:"),
  Q("I then shouted into M the following sentence: \"Mr. Watson—Come here—I want to see you.\" To my delight he came and declared that he had heard and understood what I said.",
    "Alexander Graham Bell", "Laboratory notebook, March 10, 1876", "Alexander Graham Bell Family Papers, Library of Congress", "https://www.loc.gov/collections/alexander-graham-bell-papers/", "M is the mouthpiece."),
  H("Who invented the telephone?"),
  P("This question has real disagreement, so here are the main positions."),
  LI("<b>Bell</b> held the patent, which survived hundreds of lawsuits, including cases decided by the U.S. Supreme Court. He gave the first public demonstrations and built a working system.",
     "<b>Elisha Gray</b> filed a caveat (a notice of an invention in progress) at the patent office on the same day as Bell's application, describing a liquid transmitter like the one Bell used on March 10. Some historians think Bell learned of Gray's idea; others think the timing was coincidence and Bell's own work led him there.",
     "<b>Antonio Meucci</b>, an Italian immigrant in New York, built voice-carrying devices years earlier and filed a caveat in 1871, but could not afford to renew it after 1874. His supporters say he was the first inventor; others say his devices did not work the way Bell's did."),
  P("Most historians credit Bell with the first practical telephone and the patent, while recognizing that Gray and Meucci did important work toward the same goal. Big inventions often happen to several people at once, because the ideas and parts they need are in the air."),
  TL([
   ("1847", "Bell born in Edinburgh"),
   ("1871", "Moves to Boston to teach deaf students"),
   ("1871", "Meucci files a caveat for a \"sound telegraph\""),
   ("June 2, 1875", "The stuck reed: Bell hears a twang with its overtones"),
   ("February 14, 1876", "Bell's patent application and Gray's caveat filed the same day"),
   ("March 7, 1876", "Patent 174,465 granted"),
   ("March 10, 1876", "\"Mr. Watson—Come here—I want to see you\""),
   ("1877", "Bell Telephone Company founded"),
   ("1915", "Bell and Watson open the first coast-to-coast telephone line"),
   ("1922", "Bell dies in Nova Scotia"),
  ]),
  EX("Days apart", "The patent was granted on March 7, 1876, and the first sentence was heard on March 10. How many days apart?",
     ["$10 - 7 = 3$."], "3 days."),
  H("What it led to"),
  P("By 1900 there were well over a million telephones in the United States. Bell spent much of his later life on other projects: hydrofoil boats, kites, a photophone that sent sound on a beam of light, and teaching the deaf, which he always called his true work."),
  M("Thinking the telephone sends the actual sound down the wire. It sends a changing electric current shaped like the sound; the receiver turns it back into sound."),
  TRYIT([("telegraph", "Build a telegraph, the invention Bell set out to improve"), ("crystal-radio", "Hear voices with no battery at all in a crystal radio")]),
  P("Read more: " + GK("Alexander_Graham_Bell", "Alexander Graham Bell") + " and " + GK("Telephone") + "."),
  TRY,
 ], "loc_bell", "g_bell"),

 "edison": LES([
  P("Thomas Alva Edison (1847–1931) was born in Milan, Ohio, and grew up in Port Huron, Michigan. He had only a few months of school; his mother taught him at home. As a teenager he sold newspapers on trains and then worked as a telegraph operator, which taught him electricity. He became partly deaf young, and later said it helped him concentrate."),
  K("Edison's biggest invention may have been the <b>invention factory</b>: a laboratory at Menlo Park, New Jersey (1876), with machinists, chemists and a library, where a team tested idea after idea. Its results included the <b>phonograph</b> (1877) and a <b>long-lasting light bulb</b> with a system to power it."),
  H("A first lesson"),
  P("Edison's first patent, in 1869, was an electric vote recorder for lawmakers. It worked, but nobody wanted it: lawmakers liked slow voting. Edison said later that he learned to invent things people would buy."),
  H("The phonograph, 1877"),
  P("Working on telegraph and telephone devices, Edison wondered whether a needle moved by the voice could scratch a groove, and the groove later move a needle to play the voice back. In late 1877 he had a machinist build a cylinder wrapped in tinfoil, with a needle on a diaphragm. He recited \"Mary had a little lamb,\" and the machine played it back. It made him famous."),
  H("The light bulb: trying thousands of materials"),
  P("Electric arc lights already lit some streets, but they were blinding and needed constant care. Many inventors had made glowing bulbs, including Joseph Swan in England. The problem was a bulb that would glow softly for hundreds of hours, cheaply, and a way to deliver power to homes. In 1878 Edison promised to solve it."),
  LI("<b>Why a vacuum:</b> a hot thread glowing in air burns up, because it reacts with oxygen. With most of the air pumped out, it lasts much longer. Better vacuum pumps were a key step.",
     "<b>Why a thin, high-resistance filament:</b> Edison planned to wire many lamps side by side (in parallel) from one supply. A thin filament with high resistance needs less current, so the copper wires could be thinner and cheaper.",
     "<b>What they tried:</b> platinum first, which melted or cost too much; then carbon made by baking cotton thread, paper, wood and more. In October 1879 a carbonized cotton thread glowed for more than 13 hours. Carbonized cardboard did better. Then the team tested thousands of plant fibers, and in 1880 found that carbonized bamboo could last over a thousand hours."),
  V("iv-filament", None, "Pick a filament material and a vacuum quality, then switch on. Watch how long it lasts. Too much air and almost anything burns out fast."),
  Q("The first step is an intuition—and comes with a burst, then difficulties arise … 'Bugs' as such little faults and difficulties are called show themselves and months of anxious watching, study and labor are requisite before commercial success—or failure—is certainly reached.",
    "Thomas Edison", "Letter to Theodore Puskas, November 1878", "Thomas A. Edison Papers, Rutgers University", "https://edisondigital.rutgers.edu/document/LB003487", "Shortened. This letter is one of the earliest uses of \"bug\" for a fault in a machine."),
  EX("Hours to days", "A bamboo filament lamp lasts 1,200 hours. If it burns 6 hours every night, how many nights is that?",
     ["$1200 \\div 6 = 200$."], "200 nights."),
  H("A system, not just a bulb"),
  P("A bulb is useless without power. Edison's team designed dynamos, wiring, fuses, switches, meters and sockets. On September 4, 1882, the Pearl Street Station in Lower Manhattan began sending direct current to customers. In Britain, Edison and Swan joined their companies in 1883."),
  LEGEND("<p>Some popular sayings about Edison are hard to trace, such as that he \"found 10,000 ways that won't work.\" His team really did test thousands of materials, as the notebooks show. But be careful with famous quotations: check where they come from, the way historians do.</p>"),
  TL([
   ("1847", "Born in Milan, Ohio"),
   ("1863", "Works as a telegraph operator"),
   ("1869", "First patent: the electric vote recorder"),
   ("1876", "Opens the Menlo Park laboratory"),
   ("1877", "Phonograph: \"Mary had a little lamb\""),
   ("1879", "Carbonized cotton filament glows for more than 13 hours (October)"),
   ("1880", "Carbonized bamboo filaments last over 1,000 hours"),
   ("1882", "Pearl Street Station powers lamps in New York"),
   ("1887", "Moves to a larger laboratory in West Orange, New Jersey"),
   ("1931", "Dies in West Orange, holding over a thousand U.S. patents"),
  ]),
  EX("Team speed", "Edison said his team tested about 6,000 plant fibers. Suppose that took 100 weeks. How many fibers is that per week?",
     ["$6000 \\div 100 = 60$."], "About 60 a week, more than 10 every working day."),
  H("What it led to"),
  P("The research lab, where a team works on problems full time, became the model for companies around the world. The electric light changed when people could work and read. Edison's direct current system was soon challenged by alternating current, which brings us to Tesla."),
  M("Saying Edison invented the light bulb alone. Many inventors made bulbs; Edison's team made a practical, long-lasting one and the whole system to power it, while Swan in England reached a similar bulb at about the same time."),
  TRYIT([("filament-bulb", "Explore why filaments burn in air and glow in a vacuum")]),
  P("Read more: " + GK("Thomas_Edison", "Thomas Edison") + ", " + GK("Incandescent_light_bulb", "Incandescent light bulb") + " and " + GK("Phonograph") + "."),
  TRY,
 ], "edison_papers", "g_edison"),

 "tesla": LES([
  P("Nikola Tesla (1856–1943) was born to Serbian parents in Smiljan, a village in today's Croatia, then part of the Austrian Empire. His father was a priest; his mother, he said, was an inventor of household tools. He studied engineering at the polytechnic in Graz, worked for telephone and electric companies in Budapest and Paris, and moved to New York in 1884. In 1919 he told his story in a magazine series, <i>My Inventions</i>."),
  K("Tesla's great idea was a <b>magnetic field that rotates</b>. Feed two or three coils with alternating currents that peak one after another, and the combined field turns like a spinning magnet. A metal rotor inside is dragged around. This <b>induction motor</b> needs no brushes or sliding contacts, and it made <b>alternating current (AC)</b> practical."),
  H("The problem"),
  P("Motors of the time ran on direct current and needed a commutator with brushes, sliding contacts that sparked and wore out. As a student in Graz, Tesla watched one."),
  Q("While Prof. Poeschl was making demonstrations, running the machine as a motor, the brushes gave trouble, sparking badly, and I observed that it might be possible to operate a motor without these appliances. But he declared that it could not be done.",
    "Nikola Tesla", "My Inventions, Part III (1919)", "Electrical Experimenter magazine, 1919", "https://en.wikisource.org/wiki/My_Inventions", "Shortened."),
  H("How the idea came"),
  P("Tesla says he tried for years, picturing machines in his mind. In February 1882, walking in a Budapest park with a friend at sunset and reciting lines from Goethe's <i>Faust</i>, the answer came."),
  Q("As I uttered these inspiring words the idea came like a flash of lightning and in an instant the truth was revealed. I drew with a stick on the sand the diagrams shown six years later in my address before the American Institute of Electrical Engineers, and my companion understood them perfectly.",
    "Nikola Tesla", "My Inventions, Part III (1919)", "Electrical Experimenter magazine, 1919", "https://en.wikisource.org/wiki/My_Inventions"),
  V("iv-field", None, "Each coil's current rises and falls, one after the other. Add up their fields (the arrows) and the total spins around. Slow it down to watch, or switch one phase off and see the turning stop."),
  W("Two coils at right angles, with currents a quarter-cycle apart, act like the hands of a clock: when one is strongest, the other is zero, then the other takes over. Their sum is an arrow of the same length that turns steadily, once per cycle."),
  EX("How fast does the field turn?", "A two-pole field turns once per cycle of the current. With 60 cycles per second, how many turns per minute is that?",
     ["60 turns each second.", "$60 \\times 60 = 3600$ turns per minute."], "3,600 turns per minute."),
  H("Working for Edison, and on his own"),
  P("In New York Tesla worked for about six months in 1884 for an Edison company, improving direct current dynamos. He left after a dispute about pay; in his telling, he had been promised a large bonus that was never paid, and the story is told differently by others. In 1887 he set up his own laboratory, and in May 1888 described his AC motors in a lecture to the American Institute of Electrical Engineers. George Westinghouse bought the patents."),
  H("The war of the currents"),
  P("In the late 1880s, Edison's companies sold direct current (DC) and Westinghouse sold alternating current (AC). Both sides had good arguments at the time:"),
  TB(["", "Direct current (Edison)", "Alternating current (Westinghouse, Tesla)"], [
   ("Strengths in the 1880s", "Already working in cities; good motors and meters; could charge batteries", "A transformer can step it up to high voltage for long wires and down again for homes, wasting less power on the way"),
   ("Weaknesses in the 1880s", "Power stations had to be within a mile or two of customers", "No practical motor until Tesla's; high voltages raised safety worries"),
  ], "The two systems as engineers saw them at the time."),
  P("Edison's side ran a public campaign about the dangers of AC's high voltages; the Westinghouse side answered that well-built AC was safe. AC won for power grids, mainly because transformers made long-distance power cheap. Westinghouse lit the 1893 World's Fair in Chicago with AC, and in 1896 AC power from Niagara Falls reached Buffalo, over 20 miles away. DC never disappeared: batteries, phones and computers run on it, and some very long modern power lines use high-voltage DC."),
  LEGEND("<p>Tesla is often told as a lone genius robbed by Edison. The record is more mixed. Galileo Ferraris in Italy found the rotating magnetic field independently at about the same time. Tesla was paid well for his patents, though he later gave up royalties to help Westinghouse's company, and died with little money. And Edison, though wrong about AC, was a great inventor in his own right. Both men's own words should be read as their side of the story.</p>"),
  TL([
   ("1856", "Born in Smiljan"),
   ("1875–1878", "Studies at the polytechnic in Graz; sees the sparking Gramme machine"),
   ("1882", "The rotating field idea in a Budapest park"),
   ("1884", "Arrives in New York; works for an Edison company"),
   ("1887", "Opens his own laboratory"),
   ("1888", "Lecture on AC motors; Westinghouse buys the patents"),
   ("1891", "Patents the Tesla coil"),
   ("1893", "AC lights the World's Fair in Chicago"),
   ("1896", "Power from Niagara Falls reaches Buffalo"),
   ("1919", "My Inventions published"),
   ("1943", "Dies in New York"),
  ]),
  EX("From idea to lecture", "Tesla had the idea in 1882 and lectured on it in 1888. How many years?",
     ["$1888 - 1882 = 6$."], "6 years, just as he says: \"shown six years later.\""),
  H("What it led to"),
  P("Induction motors run fans, pumps, factory machines and many electric trains. The power grid that reaches nearly every home is alternating current. The unit of magnetic field strength is named the tesla."),
  M("Thinking AC \"won\" because DC was bad. Each had strengths; transformers made AC cheaper to send far, and that settled it for the grid."),
  TRYIT([("simple-motor", "Build a simple motor"), ("hand-generator", "Make an alternating current with a magnet and a coil")]),
  P("Read more: " + GK("Nikola_Tesla", "Nikola Tesla") + ", " + GK("Induction_motor", "Induction motor") + " and " + GK("War_of_the_currents", "War of the currents") + "."),
  TRY,
 ], "tesla_mi", "g_tesla"),
}
